export const catalogueRecords: readonly CatalogueRecord[] = [
  ...weaponRecords,
  ...vehicleRecords,
  ...ammoRecords,
  ...attachmentRecords,
  ...gearRecords
];

export function getCatalogueRecords(type: CatalogueRecordType): readonly CatalogueRecord[] {
  return catalogueRecords.filter((record) => record.type === type);
}

export function getCatalogueRecord(type: CatalogueRecordType, slug: string): CatalogueRecord | undefined {
  return catalogueRecords.find((record) => record.type === type && record.slug === slug);
}
